describe('Notification Panel', () => {
    beforeEach(() => {
        cy.visit('/'); // Replace with the actual URL of the application
    });

    it('should display the notification panel sliding in from the top', () => {
        cy.get('.notification-trigger').click(); // Assuming there's a trigger to show the notification
        cy.get('.notification-panel').should('be.visible').and('have.class', 'slide-in');
    });

    it('should not display the notification panel when not triggered', () => {
        cy.get('.notification-panel').should('not.be.visible');
    });
});
